// ===== Jarvis settings: edit these two lines, then click Publish =====

const BOT_TOKEN = 'PASTE_YOUR_BOT_TOKEN_HERE';  // from @BotFather: /mybots → your bot → API Token
const OWNER_ID  = 0;                            // your Telegram user ID (a number). Leave 0 at first:
                                                // send /start to your bot and Jarvis tells you your ID.

// ===== nothing to change below =====
if (!/^\d{5,}:[A-Za-z0-9_-]{30,}$/.test(BOT_TOKEN)) {
  throw new Error('Settings: paste your bot token into BOT_TOKEN (it looks like 123456789:AAF...)');
}
return [{ json: { bot_token: BOT_TOKEN, owner_id: Number(OWNER_ID) || 0 } }];

// Telegram's answer: { ok, result: [ update, update, ... ] }
const updates = $input.first().json.result || [];
if (updates.length === 0) return [];   // nothing new: stop here

const OWNER_ID = $('Settings').first().json.owner_id;
const lastId = Math.max(...updates.map(u => u.update_id));
const mine = updates
  .map(u => u.message)
  .filter(m => m && m.from && !m.from.is_bot && m.chat && m.chat.type === 'private')
  .filter(m => OWNER_ID === 0 || m.from.id === OWNER_ID);   // 0 = setup mode: Jarvis only tells you your ID

// One item: the offset that confirms these updates, plus my messages
return [{ json: { offset: lastId + 1, messages: mine } }];

// One item per message, with what kind it is
const MAX_VOICE_SECONDS = 120;   // longer voice notes are refused (saves free credits)
return $('Keep only my messages').first().json.messages.map(m => {
  const base = { chat_id: m.chat.id, from_id: m.from.id, name: m.from.first_name || 'friend' };
  if (m.text) return { json: { ...base, kind: 'text', text: m.text.trim() } };
  if (m.voice) {
    if ((m.voice.duration || 0) > MAX_VOICE_SECONDS) return { json: { ...base, kind: 'too_long' } };
    return { json: { ...base, kind: 'voice', file_id: m.voice.file_id } };
  }
  return { json: { ...base, kind: 'other' } };
});

// Telegram calls voice files ".oga"; speech-to-text services expect ".ogg" (same format)
const item = $input.item;
if (item.binary && item.binary.data) {
  item.binary.data.fileName = 'voice.ogg';
  item.binary.data.mimeType = 'audio/ogg';
}
return item;

// Turn the transcript into a normal message, marked as "came in by voice"
const msg = $('One item per message').item.json;
const heard = ($input.item.json.text || '').trim();
if (!heard) return { json: { ...msg, kind: 'voice_failed' } };
return { json: { ...msg, kind: 'text', text: heard, voice_in: true } };

const OWNER_ID = $('Settings').first().json.owner_id;
const memory = $getWorkflowStaticData('global');   // survives between runs of this published workflow
memory.chats = memory.chats || {};

return $input.all().map(({ json: m }) => {
  const key = String(m.chat_id);
  const direct = reply => ({ json: { chat_id: m.chat_id, reply, skip_ai: true, voice_in: false } });

  if (OWNER_ID === 0) return direct(
    `Setup: your Telegram user ID is ${m.from_id}.\n\nIn n8n, open the Settings node, set OWNER_ID = ${m.from_id}, then click Publish. After that, only you can talk to me.`);
  if (m.kind === 'too_long')     return direct('That voice note is too long for me. Please keep it under 2 minutes.');
  if (m.kind === 'voice_failed') return direct("Sorry, I couldn't understand that voice note. Please try again, or type it.");
  if (m.kind === 'other')        return direct('I can read text and listen to voice notes. Other kinds of messages come later.');

  if (m.text === '/start' || m.text === '/new') {
    memory.chats[key] = [];
    return direct(m.text === '/start'
      ? `Hi ${m.name}, I'm Jarvis. Write or send me a voice note any time. Send /new to start a fresh conversation.`
      : 'OK, fresh start. I forgot our earlier conversation.');
  }

  let system = `You are Jarvis, the personal assistant of ${m.name}. ` +
    'Reply in the same language the user writes or speaks in (Urdu in Urdu script, English, Arabic...). ' +
    'Be warm, clear and brief: this is a Telegram chat on a phone. Plain text, short paragraphs, no tables. ' +
    'You cannot take actions yet (no calendar, reminders or PC control): if asked, say honestly that this skill is coming.';
  if (m.voice_in) system += ' The user spoke to you, and your answer will also be read aloud: keep it under 60 words, no lists, no symbols.';

  return { json: {
    chat_id: m.chat_id, text: m.text, voice_in: !!m.voice_in, skip_ai: false,
    body: { model: 'smart', messages: [ { role: 'system', content: system }, ...(memory.chats[key] || []), { role: 'user', content: m.text } ] }
  } };
});

const asked = $('Prepare each message').item.json;   // the message this answer belongs to
const r = $input.item.json;
let reply = r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
reply = (reply || '').trim();
if (!reply) reply = "Sorry, my brain didn't answer just now. Please try again in a minute.";

// Keep the last 10 exchanges (20 messages) per chat
const memory = $getWorkflowStaticData('global');
memory.chats = memory.chats || {};
const key = String(asked.chat_id);
memory.chats[key] = (memory.chats[key] || [])
  .concat([ { role: 'user', content: asked.text }, { role: 'assistant', content: reply } ])
  .slice(-20);

return { json: { chat_id: asked.chat_id, reply, voice_in: asked.voice_in, heard: asked.voice_in ? asked.text : '' } };

// Same shape for every answer: text to show, text to speak, and whether to speak it
const a = $input.item.json;
const shown = a.heard ? `🎙️ "${a.heard}"\n\n${a.reply}` : a.reply;   // voice in: show what Jarvis heard
return { json: { chat_id: a.chat_id, text: String(shown).slice(0, 4000), speak: a.reply, voice_in: !!a.voice_in } };
